def holes(s):
    h,w=len(s),len(s[0])
    from collections import deque
    seen=set()
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if s[i][j]==0 and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if s[i][j]==0 and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    while q:
        y,x=q.popleft()
        for a,b in((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=a<h and 0<=b<w and s[a][b]==0 and (a,b) not in seen:
                seen.add((a,b)); q.append((a,b))
    return sum(s[i][j]==0 and (i,j) not in seen for i in range(h) for j in range(w))
